const t=[{id:"l.st-systems-2.plot",xp:40,title:{en:"Solve the 22 × 40 m plot: clear height 6.5 m, the whole 40 m edge column-free — read the new eaves",ar:"حل الأرض 22 × 40 م: ارتفاع صافي 6.5 م، والحرف 40 م كله من غير أعمدة — اقرا الـ Eaves الجديدة"},check:e=>e.sys==="edge"&&e.B===22&&e.L===40&&e.clear===6.5&&e.Lf===40&&Math.abs(e.edgeEave-8.6)<.01},{id:"l.st-systems-2.hang",xp:20,title:{en:"Keep the eaves instead and compare the clear height under the heavy truss",ar:"ثبّت الـ Eaves بدل كده وقارن الارتفاع الصافي تحت الجمالون التقيل"},check:e=>e.sys==="edge"&&e.keepEave}],s=[{id:"l.st-systems-2.bow",xp:30,title:{en:"Remove the strips behind both heavy trusses",ar:"شيل الشرايح اللي ورا الجمالونين التقال"},check:e=>e.sys==="edge"&&e.both&&!e.HB2},{id:"l.st-systems-2.one",xp:20,title:{en:"Allow columns on one long side again: one heavy truss is enough",ar:"اسمح بأعمدة على ضلع طويل تاني: جمالون تقيل واحد كفاية"},check:e=>e.sys==="edge"&&!e.both}],a=[{id:"l.st-systems-2.c11",xp:30,title:{en:"An 11 m cantilever at c/5: how deep at the column?",ar:"كابولي 11 م على c/5: عمقه عند العمود قد إيه؟"},check:e=>e.sys==="overhang"&&e.ovDir==="along"&&e.c===11&&Math.abs(e.Hc-2.2)<1e-6},{id:"l.st-systems-2.c14",xp:30,title:{en:"A 14 m void edge: the cantilever is no longer allowed",ar:"حرف فتحة 14 م: الكابولي مبقاش مسموح"},check:e=>e.sys==="overhang"&&e.ovDir==="along"&&e.c>=14&&e.solution==="heavy"}],n=[{id:"l.st-systems-2.x",xp:20,title:{en:"Brace the interior line with an X and see the warning",ar:"اعمل X على الخط الداخلي وشوف التحذير"},check:e=>e.sys==="levels"&&e.lvArr==="side"&&e.interior==="x"},{id:"l.st-systems-2.13",xp:30,title:{en:"Raise the high span to 13 m clear: three tiers",ar:"علّي البحر العالي لـ 13 م صافي: تلات أدوار"},check:e=>e.sys==="levels"&&e.c2>=13}],r=[{id:"l.st-systems-2.tip",xp:40,title:{en:"Stabilise the hinged car shed with a tip truss and braced end towers",ar:"ثبّت مظلة العربيات المفصلية بجمالون طرف وأبراج طرفية مربوطة"},check:e=>e.sys==="overhang"&&e.base==="hinged"&&e.tipTruss&&e.stable},{id:"l.st-systems-2.fix",xp:20,title:{en:"Or fix the bases: no tip truss needed",ar:"أو ثبّت القواعد: مش محتاج جمالون طرف"},check:e=>e.sys==="overhang"&&e.base==="fixed"&&!e.tipTruss&&e.stable}],o=[{id:"l.st-systems-2.ws-hinge",xp:30,title:{en:"Your canopy on hinged bases: what happens?",ar:"مظلتك على قواعد مفصلية: إيه اللي بيحصل؟"},check:e=>e.sys==="overhang"&&e.c===5&&e.base==="hinged"&&!e.stable},{id:"l.st-systems-2.ws-6",xp:20,title:{en:"Stretch your canopy to 6 m: the depth at the column grows to 1.2 m",ar:"طوّل مظلتك لـ 6 م: العمق عند العمود بيكبر لـ 1.2 م"},check:e=>e.sys==="overhang"&&e.c===6&&Math.abs(e.Hc-1.2)<1e-6}],i={sections:[{id:"method",title:{en:"A method for any plot",ar:"طريقة لأي أرض"},blocks:[{t:"p",text:{en:"This episode is a studio: a series of awkward plots, each solved with the rules you already have. Every exam-style layout problem is attacked in the same order:",ar:"الحلقة دي ستوديو: مجموعة أراضي صعبة، كل واحدة بتتحل بالقواعد اللي عندك. وكل مسألة تخطيط من نوع الامتحانات بتتهاجم بنفس الترتيب:"}},{t:"steps",items:[{en:"Mark the lines where columns are **allowed** (usually the solid lines of the plot) and the clear heights.",ar:"علّم الخطوط اللي **مسموح** فيها أعمدة (غالبًا الخطوط المتصلة في الأرض) والارتفاعات الصافية."},{en:"Lay the main trusses across the **short direction** wherever they find columns at both ends.",ar:"حط الجمالونات الرئيسية على **الاتجاه القصير** في كل حتة بتلاقي فيها أعمدة من الطرفين."},{en:"Where a support is missing: a **purlin cantilever** up to 2.5 m, a **cantilever truss** up to 12 m, otherwise a **heavy truss** (depth span/(10–12), never less than the depth of the trusses it carries **where they sit on it**).",ar:"مكان ما الركيزة ناقصة: **كابولي مدادات** لحد 2.5 م، و**جمالون كابولي** لحد 12 م، وإلا **جمالون تقيل** (عمقه البحر/(10–12)، ومش أقل من عمق الجمالونات اللي شايلها **عند ارتكازها عليه**)."},{en:"Fix the **levels**: the clear height is measured under the lowest member (the heavy truss); upper chords meet at the same level; eaves = clear + H_heavy − h.",ar:"ثبّت **المناسيب**: الارتفاع الصافي بيتقاس تحت أوطى عضو (الجمالون التقيل)؛ والأوتار العلوية بتتقابل في نفس المنسوب؛ والـ Eaves = الصافي + H_heavy − h."},{en:"Bracing: **every roof braced at both of its ends**, strips **behind every heavy truss**, vertical bracing on every braced wall line (a heavy truss counts as one), struts from 6 m of clear height, portal bracing where a passage must stay open.",ar:"الشكالات: **كل سقف عليه شكالات عند طرفيه**، وشرايح **ورا كل جمالون تقيل**، وشكالات رأسية على كل خط حائط فيه شكالات (والجمالون التقيل بيتحسب واحد منهم)، وعضو أفقي من 6 م ارتفاع صافي، وشكالة بوابية مكان ما الممر لازم يفضل مفتوح."},{en:"Longitudinal bracing ≤ 8 m apart, and at every cantilever tip; its depth is the truss depth on its line.",ar:"شكالات طولية كل ≤ 8 م، وعند كل طرف كابولي؛ وعمقها عمق الجمالون على خطها."},{en:"Draw the plan, the main-system sections, the end gables and the bracing elevations — and check both load paths.",ar:"ارسم المسقط وقطاعات النظام الرئيسي والواجهات الطرفية وواجهات الشكالات — وراجع مسارين الأحمال."}]},{t:"quiz",q:{kind:"mcq",q:{en:"A support is missing 9 m from the nearest column line, along the trusses. The first choice is…",ar:"ركيزة ناقصة على بعد 9 م من أقرب خط أعمدة، في اتجاه الجمالونات. الاختيار الأول…"},options:[{en:"a cantilever truss",ar:"جمالون كابولي"},{en:"a purlin cantilever",ar:"كابولي مدادات"},{en:"a heavy truss",ar:"جمالون تقيل"}],answer:0,explain:{en:"9 m ≤ 12 m: a cantilever truss (H = c/(5–8)) does it; purlins stop at 2.5 m.",ar:"9 م ≤ 12 م: الجمالون الكابولي (H = c/(5–8)) بيعملها؛ والمدادات بتقف عند 2.5 م."}}}]},{id:"edge",title:{en:"A long edge without columns: the roof goes up",ar:"حرف طويل من غير أعمدة: السقف بيطلع"},blocks:[{t:"p",text:{en:"**Plot: 22 × 40 m, clear height 6.5 m, no columns along one 40 m edge.** Main trusses across the 22 m: $H = 22/12 = 1.83 \\to 1.80$ m; at 20:1, $h = 1.80 - 11/20 = 1.25$ m ✓; fourteen panels of 1.571 m; 8 bays of 5 m. A heavy truss on the free edge: $40/12 = 3.33 \\to 3.35$ m (rounded up, so that it stays inside $40/(10\\sim12) = 3.33$–$4.00$ m) ≥ 1.25 m, the depth of the trusses where they sit on it ✓, panels of 2.5 m (53.3°). **Levels:** 6.5 m clear under the heavy truss → its lower chord at 6.5 m and its upper chord at 9.85 m; the main upper chords meet it there, so the ordinary eaves (the lower chord at the columns) rise to $9.85 - 1.25 = 8.60$ m and the ridge to $9.85 + 0.55 = 10.40$ m. The **longitudinal bracing** lines (at 7.86 and 14.14 m) are $1.25 + 7.86/20 = 1.64$ m deep — the truss depth on their line.",ar:"**الأرض: 22 × 40 م، ارتفاع صافي 6.5 م، ومفيش أعمدة على حرف طوله 40 م.** الجمالونات الرئيسية على الـ 22 م: $H = 22/12 = 1.83 \\to 1.80$ م؛ عند 20:1، $h = 1.80 - 11/20 = 1.25$ م ✓؛ أربعتاشر باكية كل واحدة 1.571 م؛ و 8 باكيات كل واحدة 5 م. وجمالون تقيل على الحرف الحر: $40/12 = 3.33 \\to 3.35$ م (متقرّب لفوق، علشان يفضل جوه $40/(10\\sim12) = 3.33$–$4.00$ م) ≥ 1.25 م، عمق الجمالونات عند ارتكازها عليه ✓، بواكيه 2.5 م (53.3°). **المناسيب:** 6.5 م صافي تحت الجمالون التقيل ← وتره السفلي عند 6.5 م والعلوي عند 9.85 م؛ والأوتار العلوية الرئيسية بتقابله هناك، فالـ Eaves العادية (الوتر السفلي عند الأعمدة) بتطلع لـ $9.85 - 1.25 = 8.60$ م والـ Ridge لـ $9.85 + 0.55 = 10.40$ م. وخطوط **الشكالات الطولية** (عند 7.86 و 14.14 م) عمقها $1.25 + 7.86/20 = 1.64$ م — عمق الجمالون على خطها."}},{t:"p",text:{en:"With a factored roof load of 1.2 kN/m² each truss end brings $R = 1.2\\times5\\times22/2 = 66$ kN; seven of them give $M = 2640$ kN·m and a chord force $C = 2640/3.35 = 788$ kN, and each corner cross column takes $231 + 33 = 264$ kN.",ar:"وبحمل سقف مضروب 1.2 kN/m² كل طرف جمالون بيجيب $R = 1.2\\times5\\times22/2 = 66$ kN؛ وسبعة منهم بيدّوا $M = 2640$ kN·m وقوة وتر $C = 2640/3.35 = 788$ kN، وكل عمود صليبة في الركن بياخد $231 + 33 = 264$ kN."}},{t:"note",tone:"tip",text:{en:"**Tools combine.** Say the last 15 m of one long wall must stay free and a 5 m canopy runs along the other wall and across the far end: a heavy truss spans the free 15 m and **cantilevers** another 5 m; on the opposite wall a 5 m cantilevering heavy truss (an overhang across the trusses beyond 2.5 m); the canopy truss at the far end rests on the two tips; and the main trusses **cantilever** 5 m over the side canopy. Every piece is one rule you already know.",ar:"**الأدوات بتتجمع.** افرض آخر 15 م من حائط طويل لازم يفضل فاضي، ومظلة 5 م ماشية على الحائط التاني وعلى الواجهة البعيدة: جمالون تقيل بيعدّي الـ 15 م الفاضيين و**بيكمّل كابولي** 5 م كمان؛ وعلى الحائط المقابل جمالون تقيل كابولي 5 م (كابولي عمودي على الجمالونات أكتر من 2.5 م)؛ وجمالون المظلة عند الطرف البعيد راكب على الطرفين؛ والجمالونات الرئيسية **بتكمّل كابولي** 5 م فوق المظلة الجانبية. كل حتة فيهم قاعدة انت عارفها."}},{t:"p",text:{en:"**Bracing the combined plan.** In the combined plan of the tip above (a free 15 m wall and two canopies), the canopy bay at the far end is the end of the roof: it is braced like an end bay, over the whole width including the side canopy. The H.B2 strip behind the 15 m heavy truss runs between braced bays; the canopy truss at the far end has no columns at all (it rests on the two tips); and every longitudinal line runs on into the canopies, with one more line along the tip of the side canopy.",ar:"**شكالات الأرض المركبة.** في الأرض المركبة اللي في الملاحظة اللي فوق (حائط 15 م فاضي ومظلتين)، باكية المظلة عند الطرف البعيد هي آخر السقف: بتاخد شكالات زي أي باكية طرفية، على العرض كله ومعاه المظلة الجانبية. وشريط الـ H.B2 اللي ورا الجمالون التقيل 15 م ماشي بين باكيات فيها شكالات؛ وجمالون المظلة عند الطرف البعيد مالوش أعمدة خالص (راكب على الطرفين)؛ وكل خط شكالات طولية بيكمل جوه المظلات، وخط زيادة بطول طرف المظلة الجانبية."}},{t:"p",text:{en:"**On an eaves line the heavy truss may be shallow.** Its floor is the depth of the trusses **where they sit on it** — on an eaves line only their end depth h, not their ridge depth. When the range span/(10–12) reaches down to h — that is, when $L_h/12 \\le h$ — the heavy truss can be exactly h deep: the lower chords then meet it level, nothing is inclined and nothing is lifted. **Example — a 28 × 48 m shed** (8 bays of 6 m, clear height 6.0 m) with the first 18 m of one long wall column-free. The 28 m trusses are 2.30 m deep at the ridge and 1.60 m at the columns (20:1). The heavy truss: $18/12 = 1.50$ to $18/10 = 1.80$ m, and not less than 1.60 m → take **1.60 m = h**. Four panels of 1.5 m per bay put its diagonals at $\\tan^{-1}(1.6/1.5) = 46.8^\\circ$. Levels: every lower chord at 6.0 m, the upper chords at 7.6 m at the walls, the ridge at 8.3 m — the eaves stay at 6.0 m. Forces at 1.2 kN/m²: $R = 1.2\\times6\\times28/2 = 100.8$ kN, two seats at the third points, $M = 100.8\\times6 = 604.8$ kN·m and $C = 604.8/1.60 = 378$ kN. Sized against the 2.30 m ridge depth instead, the heavy truss would have been 0.70 m deeper and would have lifted the whole roof by $2.30 - 1.60 = 0.70$ m.",ar:"**على خط الـ Eaves الجمالون التقيل ممكن يبقى قليل العمق.** الحد الأدنى لعمقه هو عمق الجمالونات **عند ارتكازها عليه** — وعلى خط الـ Eaves ده عمقها عند طرفها h بس، مش عمقها عند الـ Ridge. ولما مدى البحر/(10–12) ينزل لحد h — يعني لما $L_h/12 \\le h$ — الجمالون التقيل ينفع يبقى عمقه h بالظبط: الأوتار السفلية بتقابله في نفس المنسوب، ومفيش حاجة مايلة ولا حاجة بتطلع. **مثال — هنجر 28 × 48 م** (8 باكيات كل واحدة 6 م، وارتفاع صافي 6.0 م) وأول 18 م من حائط طويل من غير أعمدة. جمالونات الـ 28 م عمقها 2.30 م عند الـ Ridge و 1.60 م عند الأعمدة (20:1). الجمالون التقيل: $18/12 = 1.50$ لحد $18/10 = 1.80$ م، ومش أقل من 1.60 م ← خد **1.60 م = h**. أربع بواكي كل واحدة 1.5 م في الباكية بتخلي أقطاره بزاوية $\\tan^{-1}(1.6/1.5) = 46.8^\\circ$. المناسيب: كل الأوتار السفلية عند 6.0 م، والأوتار العلوية عند 7.6 م عند الحوائط، والـ Ridge عند 8.3 م — والـ Eaves بتفضل عند 6.0 م. والقوى بحمل 1.2 kN/m²: $R = 1.2\\times6\\times28/2 = 100.8$ kN، وارتكازين عند التلتين، و $M = 100.8\\times6 = 604.8$ kN·m و $C = 604.8/1.60 = 378$ kN. ولو كنا قسناه على عمق الـ Ridge 2.30 م، الجمالون التقيل كان هيبقى أعمق بـ 0.70 م وكان هيطلّع السقف كله $2.30 - 1.60 = 0.70$ م."}},{t:"lab",lab:"shed",height:500,props:{preset:"edge",missions:t,defaultTab:"inputs"},caption:{en:"Start from the 18 × 36 m heavy-truss shed and turn it into the 22 × 40 m plot.",ar:"ابدأ من هنجر الجمالون التقيل 18 × 36 م وحوّله للأرض 22 × 40 م."}},{t:"quiz",q:{kind:"num",q:{en:"Clear height 6 m under a 2.8 m heavy truss; main trusses 1.25 m deep at the columns. The ordinary eaves (m)?",ar:"ارتفاع صافي 6 م تحت جمالون تقيل 2.8 م؛ والجمالونات الرئيسية 1.25 م عند الأعمدة. الـ Eaves العادية (م)؟"},answer:7.55,tol:.002,unit:"m",explain:{en:"$6 + 2.8 - 1.25 = 7.55$ m.",ar:"$6 + 2.8 - 1.25 = 7.55$ م."}}}]},{id:"corners",title:{en:"Columns at the four corners only",ar:"أعمدة في الأركان الأربعة بس"},blocks:[{t:"p",text:{en:"When columns are allowed only at the corners, **both long edges** get a heavy truss (case 1 on each), with cross columns at the four corners. Every main truss rests on heavy trusses at **both** ends — its lower chord inclined at both ends — and the end trusses sit directly on the corner columns. The long sides need no X bracing: the heavy trusses do that job. The roof is braced in its end bays and by strips along **both** heavy trusses.",ar:"لما الأعمدة مسموحة في الأركان بس، **الحرفين الطوال** بياخدوا جمالون تقيل (الحالة 1 في كل واحد)، وأعمدة صليبة في الأركان الأربعة. وكل جمالون رئيسي راكب على جمالونات تقيلة من **الطرفين** — وتره السفلي مايل من الناحيتين — والجمالونات الطرفية قاعدة على أعمدة الأركان على طول. والضلعين الطوال مش محتاجين X: الجمالونات التقيلة بتعمل الشغلانة دي. والسقف عليه شكالات في باكياته الطرفية وشرايح بطول **الجمالونين** التقال."}},{t:"p",text:{en:"**Example — 16 × 30 m, clear height 6 m.** Main trusses 1.65 m deep (1.25 m at the ends); heavy trusses $30/12 = 2.50$ m, panels of 3 m (39.8°); upper chords at 8.5 m, the end trusses' eaves at 7.25 m. Each truss end brings $R = 1.2\\times6\\times16/2 = 57.6$ kN; four seats give $M = 1037$ kN·m and $C = 1037/2.5 = 415$ kN per heavy truss; each corner column carries $115.2 + 28.8 = 144$ kN.",ar:"**مثال — 16 × 30 م، ارتفاع صافي 6 م.** الجمالونات الرئيسية عمقها 1.65 م (1.25 م عند الأطراف)؛ والجمالونات التقيلة $30/12 = 2.50$ م، بواكيها 3 م (39.8°)؛ والأوتار العلوية عند 8.5 م، والـ Eaves بتاعة الجمالونات الطرفية عند 7.25 م. كل طرف جمالون بيجيب $R = 1.2\\times6\\times16/2 = 57.6$ kN؛ وأربع ارتكازات بيدّوا $M = 1037$ kN·m و $C = 1037/2.5 = 415$ kN في كل جمالون تقيل؛ وكل عمود ركن شايل $115.2 + 28.8 = 144$ kN."}},{t:"p",text:{en:"**No gable columns either.** Columns are allowed only at the corners, so the end walls get none: the end trusses span from corner to corner with no gable columns and no end girts, and the two ends stay open like the long sides.",ar:"**ولا أعمدة واجهة كمان.** الأعمدة مسموحة في الأركان بس، يبقى الحوائط الطرفية مفيهاش أعمدة: الجمالونات الطرفية بتعدّي من ركن لركن من غير أعمدة واجهة ولا Girts طرفية، والطرفين بيفضلوا مفتوحين زي الضلعين الطوال."}},{t:"lab",lab:"shed",height:500,props:{preset:"corners",missions:s,defaultTab:"results"},caption:{en:"A 16 × 30 m roof on four corner columns.",ar:"سقف 16 × 30 م على أربع أعمدة أركان."}},{t:"quiz",q:{kind:"num",q:{en:"A heavy truss 2.5 m deep with M = 1037 kN·m: its chord force (kN)?",ar:"جمالون تقيل عمقه 2.5 م و M = 1037 kN·m: قوة وتره (kN)؟"},answer:414.8,tol:.003,unit:"kN",explain:{en:"$C = M/H = 1037/2.5 = 414.8$ kN.",ar:"$C = M/H = 1037/2.5 = 414.8$ kN."}}}]},{id:"notches",title:{en:"Notches and side voids",ar:"النواقص والفتحات الجانبية"},blocks:[{t:"p",text:{en:"**A notch in the middle of a short side** (columns allowed on its faces). Full-length trusses run where the plot is complete; the two **wings** beside the notch get short, **mono-pitch** trusses that continue the main roof slope, with columns on the notch faces. **Example:** 28 m trusses ($H = 2.30$ m, $h = 1.60$ m at 20:1) and a 12 m wide notch in the middle of the 28 m end, which leaves two wings 8 m wide: the wing trusses rise from 1.60 m at the outer wall to $1.60 + 8/20 = 2.00$ m at the notch face — the depth of the main truss on that line.",ar:"**نقص في نص ضلع قصير** (والأعمدة مسموحة على وشوشه). الجمالونات الكاملة ماشية مكان ما الأرض كاملة؛ و**الجناحين** اللي جنب النقص بياخدوا جمالونات قصيرة **بميل واحد** بتكمّل ميل السقف الرئيسي، وأعمدة على وشوش النقص. **مثال:** جمالونات 28 م ($H = 2.30$ م و $h = 1.60$ م عند 20:1) ونقص عرضه 12 م في نص الطرف اللي عرضه 28 م، فبيفضل جناحين عرض كل واحد 8 م: جمالونات الجناح بتعلى من 1.60 م عند الحائط الخارجي لـ $1.60 + 8/20 = 2.00$ م عند وش النقص — عمق الجمالون الرئيسي على الخط ده."}},{t:"p",text:{en:"**The notch, line by line.** Take that plot as 28 × 48 m with the notch 12 m deep (two bays of 6 m; the main part six bays). The 28 m trusses have 14 panels of 2.0 m and their longitudinal lines at 8, 14 and 20 m — exactly on the two notch faces and on the ridge. (1) The truss on the **notch face** is one full 28 m truss on five columns: the two walls, the two notch corners (8 and 20 m) and one between them (14 m); between the corners its lower part is a wall, clad with girts. (2) Each **wing** is 8 m wide: four panels of 2.0 m, diagonals at 38.7° and 45.0°; its end gable is mono-pitch, with a gable column at mid-width. (3) **Roof bracing:** the main part over its full width in its first bay at the notch and in its far end bay (24 m apart ✓); each wing in its own outer bay. (4) **Vertical bracing:** the outer walls in all three braced bays; each inner wing wall (a side face of the notch) only in the braced bay of its wing — beyond the notch-face truss the same line has no columns and becomes a **longitudinal-bracing band 2.00 m deep**, with V's in the braced bays of the main part. (5) The ridge line (2.30 m) starts at the notch-face truss; a line that falls inside a wing would run its whole length, through the wing and the main part alike.",ar:"**النقص، خط خط.** خد الأرض دي 28 × 48 م والنقص عمقه 12 م (باكيتين كل واحدة 6 م؛ والجزء الرئيسي ست باكيات). جمالونات الـ 28 م فيها 14 باكية كل واحدة 2.0 م، وخطوط شكالاتها الطولية عند 8 و 14 و 20 م — بالظبط على وشّين النقص وعلى الـ Ridge. (1) الجمالون اللي على **وش النقص** جمالون واحد كامل 28 م على خمس أعمدة: الحائطين، وركنين النقص (عند 8 و 20 م)، وواحد بينهم (عند 14 م)؛ وبين الركنين الجزء اللي تحته حائط، متكسي بـ Girts. (2) كل **جناح** عرضه 8 م: أربع بواكي كل واحدة 2.0 م، والأقطار عند 38.7° و 45.0°؛ وواجهته الطرفية بميل واحد، وعمود واجهة في نص عرضها. (3) **شكالات السقف:** الجزء الرئيسي على عرضه كله في أول باكية عند النقص وفي باكيته الطرفية البعيدة (بينهم 24 م ✓)؛ وكل جناح في باكيته البرانية. (4) **الشكالات الرأسية:** الحوائط الخارجية في التلات باكيات اللي فيها شكالات؛ وكل حائط داخلي للجناح (وش جانبي للنقص) في باكية شكالات جناحه بس — وبعد جمالون وش النقص نفس الخط مفيهوش أعمدة وبيبقى **شريط شكالات طولية عمقه 2.00 م**، بـ V في باكيات شكالات الجزء الرئيسي. (5) خط الـ Ridge (2.30 م) بيبدأ من جمالون وش النقص؛ وأي خط يقع جوه جناح بيمشي على طوله كله، في الجناح والجزء الرئيسي مع بعض."}},{t:"p",text:{en:"**A void along a long side, no columns inside it.** The trusses that cross the void must cantilever from the far columns. **Up to 12 m** a cantilever truss does it, and the rule for mixing cantilever and regular trusses under one roof is: **the same upper chord, the same clear height, and the larger of the two depths for all of them** (the purlins run over both). Example: an 18 m wide plot with a 7 m deep void → 11 m cantilevers: $H = c/(5\\sim8)$, at the deeper end $11/5 = 2.20$ m, against 1.70 m for the regular trusses → every truss 2.20 m deep. **Beyond 12 m** the cantilever is not allowed: a heavy truss is laid along the edge of the void, spanning its length and resting on the full trusses at its ends — a heavy truss on heavy trusses. Example: a 20 m plot with a 6 m deep, 10 m long void would need 14 m cantilevers ✗ → a 10 m heavy truss on the two neighbouring trusses, which become heavy trusses themselves (the same shape, heavier members). $10/12 = 0.83$ m is far too small, so it takes the depth of the trusses on its line, 6 m from the wall: $1.25 + 6/20 = 1.55$ m (their 1.75 m ridge depth is not needed); and the trusses over the void span 14 m from it to the far columns.",ar:"**فتحة على ضلع طويل، ومفيش أعمدة جواها.** الجمالونات اللي بتعدّي الفتحة لازم تبقى كابولي من الأعمدة البعيدة. **لحد 12 م** الجمالون الكابولي بيعملها، وقاعدة خلط الجمالونات الكابولي والعادية تحت سقف واحد: **نفس الوتر العلوي، ونفس الارتفاع الصافي، والعمق الأكبر من الاتنين للكل** (المدادات ماشية فوق الاتنين). مثال: أرض عرضها 18 م وفتحة عمقها 7 م ← كوابيل 11 م: $H = c/(5\\sim8)$، وعند الناحية الأعمق $11/5 = 2.20$ م، قصاد 1.70 م للجمالونات العادية ← كل الجمالونات عمقها 2.20 م. **وبعد 12 م** الكابولي مش مسموح: جمالون تقيل بيتحط على حرف الفتحة، بحره طول الفتحة وراكب على الجمالونات الكاملة اللي عند طرفيها — جمالون تقيل على جمالونات تقيلة. مثال: أرض 20 م وفتحة عمقها 6 م وطولها 10 م كانت هتحتاج كوابيل 14 م ✗ ← جمالون تقيل 10 م على الجمالونين الجيران، واللي بيبقوا هما نفسهم جمالونات تقيلة (نفس الشكل، وأعضاء أتقل). و $10/12 = 0.83$ م صغيرة قوي، فبياخد عمق الجمالونات على خطه، على بعد 6 م من الحائط: $1.25 + 6/20 = 1.55$ م (مش محتاج عمق الـ Ridge بتاعها 1.75 م)؛ والجمالونات اللي فوق الفتحة بحرها 14 م منه للأعمدة البعيدة."}},{t:"p",text:{en:"**What the mixing rule does to the shapes.** One upper chord and one (larger) depth for every truss mean **parallel chords**: the regular trusses become as deep at their columns as at their ridge, both chords pitched at the roof slope, and the clear height is the same under every column end. If the void reaches the ridge line, the cantilever ends exactly there and its chords **rise** all the way to the tip. **Example:** a 15 m wide plot with a 7.5 m deep void along one long side. Regular trusses: $15/(12\\sim16) = 0.94$–$1.25$ m → 1.25 m; cantilevers: $c/(5\\sim8) = 7.5/8 = 0.94$ to $7.5/5 = 1.50$ m → **1.50 m for all of them**, chords parallel at 1:20. Ten panels of 1.5 m per truss (five in a cantilever, whose tip lies on the ridge line) put the diagonals at $\\tan^{-1}(1.5/1.5) = 45^\\circ$, and each cantilever rises $7.5/20 = 0.375$ m from its column to its tip.",ar:"**قاعدة الخلط بتعمل إيه في الأشكال.** وتر علوي واحد وعمق واحد (الأكبر) لكل الجمالونات معناهم **أوتار متوازية**: الجمالونات العادية بيبقى عمقها عند أعمدتها قد عمقها عند الـ Ridge، والوترين مايلين بميل السقف، والارتفاع الصافي واحد تحت كل طرف عمود. ولو الفتحة واصلة لخط الـ Ridge، الكابولي بيخلص هناك بالظبط وأوتاره **بتطلع** على طول لحد الطرف. **مثال:** أرض عرضها 15 م وفيها فتحة عمقها 7.5 م على ضلع طويل. الجمالونات العادية: $15/(12\\sim16) = 0.94$–$1.25$ م ← 1.25 م؛ والكوابيل: $c/(5\\sim8) = 7.5/8 = 0.94$ لحد $7.5/5 = 1.50$ م ← **1.50 م للكل**، والأوتار متوازية بميل 1:20. عشر بواكي كل واحدة 1.5 م في الجمالون (وخمسة في الكابولي، اللي طرفه على خط الـ Ridge) بيخلّوا الأقطار عند $\\tan^{-1}(1.5/1.5) = 45^\\circ$، وكل كابولي بيطلع $7.5/20 = 0.375$ م من عموده لطرفه."}},{t:"p",text:{en:"**Bracing round a void.** Roof bracing goes only into bays that are complete across the width: an end braced bay that the void cuts is stepped as in a notched end bay, and a middle braced bay moves to the first complete bay beside the void. The line of the cantilever tips — or the void-edge heavy truss — runs as a longitudinal line along the whole building. A void-edge heavy truss gets its H.B2 strip along the void bays, and the strip ends in complete braced bays on both sides, so that its reactions reach vertical bracing.",ar:"**الشكالات حوالين الفتحة.** شكالات السقف بتتحط بس في الباكيات الكاملة بعرض الأرض: الباكية الطرفية اللي الفتحة قاطعاها شكالاتها بتتدرج زي الباكية الطرفية الناقصة، والباكية اللي في النص بتتنقل لأول باكية كاملة جنب الفتحة. وخط أطراف الكوابيل — أو الجمالون التقيل اللي على حرف الفتحة — بيمشي كخط شكالات طولية بطول المبنى كله. والجمالون التقيل اللي على حرف الفتحة ليه شريط H.B2 بطول باكيات الفتحة، والشريط بيخلص في باكيات كاملة فيها شكالات من الناحيتين، علشان ردود أفعاله توصل للشكالات الرأسية."}},{t:"lab",lab:"shed",height:500,props:{preset:"carShed",missions:a,defaultTab:"steps"},caption:{en:"The cantilever trusses of the Explorer: try the 11 m and the 14 m cases.",ar:"الجمالونات الكابولي في المستكشف: جرّب حالتي الـ 11 م والـ 14 م."}},{t:"quiz",q:{kind:"num",q:{en:"Regular trusses 1.60 m deep share a roof with 12 m cantilever trusses at c/5. The depth taken for all of them (m)?",ar:"جمالونات عادية عمقها 1.60 م شايلة سقف مع جمالونات كابولي 12 م على c/5. العمق اللي بيتاخد للكل (م)؟"},answer:2.4,tol:.003,unit:"m",explain:{en:"The larger of $12/5 = 2.40$ m and 1.60 m: 2.40 m.",ar:"الأكبر بين $12/5 = 2.40$ م و 1.60 م: يعني 2.40 م."}}}]},{id:"levels",title:{en:"Two spans, two heights, and a passage",ar:"بحرين وارتفاعين وممر"},blocks:[{t:"p",text:{en:"**Two spans on an interior column line.** Portal bracing on the interior line keeps the passage between the two halves open; the outer walls take ordinary X bracing, with a mid-height strut when the clear height is 6 m or more. **Two heights side by side:** the interior columns run up to the high trusses and carry the low trusses on the way; portal bracing up to the low eaves, X above the low roof. **Two heights with a column-free edge:** the heavy truss steps with the roof (or two heavy trusses, one per level, share the line), each part keeping its clear height under its own heavy truss, and each roof braced at both of its ends. A block about 13 m high takes **three** tiers of vertical bracing.",ar:"**بحرين على خط أعمدة داخلي.** الشكالة البوابية على الخط الداخلي بتسيب الممر بين النصين مفتوح؛ والحوائط الخارجية بتاخد X عادية، بعضو أفقي في النص لو الارتفاع الصافي 6 م أو أكتر. **ارتفاعين جنب بعض:** الأعمدة الداخلية بتطلع لحد الجمالونات العالية وبتشيل الجمالونات الواطية في طريقها؛ وشكالة بوابية لحد الـ Eaves الواطية، و X فوق السقف الواطي. **ارتفاعين مع حرف من غير أعمدة:** الجمالون التقيل بيتدرج مع السقف (أو جمالونين تقال، واحد لكل منسوب، على نفس الخط)، وكل جزء محافظ على ارتفاعه الصافي تحت جمالونه التقيل، وكل سقف عليه شكالات عند طرفيه. والبلوك اللي ارتفاعه حوالي 13 م بياخد **تلات** أدوار شكالات رأسية."}},{t:"p",text:{en:"**Example — 30 × 36 m in two 15 m spans, 5.5 m and 9.0 m clear.** Each span has its own 15 m trusses (1.625 m at mid-span, 1.25 m at the columns). On the interior line: portal bracing up to 5.5 m, X from the low eaves at 6.75 m to the high eaves. The low walls take one X; the high walls two tiers with a strut at 4.5 m.",ar:"**مثال — 30 × 36 م على بحرين كل واحد 15 م، صافي 5.5 م و 9.0 م.** كل بحر ليه جمالوناته 15 م (1.625 م في النص و 1.25 م عند الأعمدة). وعلى الخط الداخلي: شكالة بوابية لحد 5.5 م، و X من الـ Eaves الواطية عند 6.75 م للـ Eaves العالية. والحوائط الواطية X واحدة؛ والعالية دورين بعضو أفقي عند 4.5 م."}},{t:"lab",lab:"shed",height:500,props:{preset:"levelsSide",missions:n,defaultTab:"inputs"},caption:{en:"Two spans at two heights with portal bracing on the interior line.",ar:"بحرين بارتفاعين وشكالة بوابية على الخط الداخلي."}},{t:"quiz",q:{kind:"num",q:{en:"A block with 13 m clear height: tiers of vertical bracing (at most 6 m each)?",ar:"بلوك ارتفاعه الصافي 13 م: أدوار الشكالات الرأسية (كل دور 6 م بالكتير)؟"},answer:3,tol:.001,explain:{en:"$\\lceil 13/6 \\rceil = 3$ tiers of about 4.3 m.",ar:"$\\lceil 13/6 \\rceil = 3$ أدوار كل واحد حوالي 4.3 م."}}}]},{id:"steps",title:{en:"Steps over a column-free edge: a stepped heavy truss, or two on one line",ar:"درجة فوق حرف من غير أعمدة: جمالون تقيل متدرج، أو اتنين على نفس الخط"},blocks:[{t:"p",text:{en:"When a roof with two clear heights also has a column-free long edge, **one heavy truss can follow the step**. It stands on cross columns at its two ends only and is sized on its whole span, span/(10–12). Over the high part its chords sit at the high levels, over the low part at the low ones; in the **panel (or bay) before the step the lower chord slopes down**, in the **panel after it the upper chord slopes down**, and on the step axis a **full-height vertical** carries both seats — the high truss at its top, the low truss lower down. Each part keeps its own clear height under its own part of the heavy truss.",ar:"لما سقف بارتفاعين صافيين يبقى فيه كمان حرف طويل من غير أعمدة، **جمالون تقيل واحد ممكن يمشي مع الدرجة**. واقف على أعمدة صليبة عند طرفيه بس، وبيتحسب على بحره كله، البحر/(10–12). فوق الجزء العالي أوتاره في المناسيب العالية، وفوق الواطي في المناسيب الواطية؛ وفي **الباكية اللي قبل الدرجة الوتر السفلي بينزل مايل**، وفي **الباكية اللي بعدها الوتر العلوي بينزل مايل**، وعلى محور الدرجة **قائم بالارتفاع كله** شايل الارتكازين — الجمالون العالي فوقه، والواطي تحت منه. وكل جزء محافظ على ارتفاعه الصافي تحت الجزء بتاعه من الجمالون التقيل."}},{t:"p",text:{en:"**Example — the 18 × 36 m shed of the previous episode** (the whole 36 m wall column-free, heavy truss $36/12 = 3.0$ m, trusses 1.25 m at the columns and 1.70 m at the ridge, six bays of 6 m), with its first three bays raised to 9.5 m clear. Low part: heavy-truss lower chord at 6.0 m, upper chord at 9.0 m, eaves 7.75 m, ridge 9.45 m. High part: 9.5 m and 12.5 m, eaves $12.5 - 1.25 = 11.25$ m, ridge 12.95 m. The step is 3.5 m: the lower chord slopes from 9.5 to 6.0 m across bay 3 ($\\tan^{-1}(3.5/6) = 30.3^\\circ$), the upper chord from 12.5 to 9.0 m across bay 4, and the vertical on the step axis is $12.5 - 6.0 = 6.5$ m tall. Each roof is braced at both of its own ends (bays 1 and 3, bays 4 and 6), and the longitudinal lines step on the step axis.",ar:"**مثال — الهنجر 18 × 36 م بتاع الحلقة اللي فاتت** (الحائط 36 م كله من غير أعمدة، وجمالون تقيل $36/12 = 3.0$ م، والجمالونات 1.25 م عند الأعمدة و 1.70 م عند الـ Ridge، وست باكيات كل واحدة 6 م)، وأول تلات باكيات فيه اتعلّوا لـ 9.5 م صافي. الجزء الواطي: الوتر السفلي للجمالون التقيل عند 6.0 م، والعلوي عند 9.0 م، والـ Eaves عند 7.75 م، والـ Ridge عند 9.45 م. الجزء العالي: 9.5 م و 12.5 م، والـ Eaves عند $12.5 - 1.25 = 11.25$ م، والـ Ridge عند 12.95 م. الدرجة 3.5 م: الوتر السفلي نازل من 9.5 لـ 6.0 م على الباكية 3 ($\\tan^{-1}(3.5/6) = 30.3^\\circ$)، والعلوي من 12.5 لـ 9.0 م على الباكية 4، والقائم اللي على محور الدرجة طوله $12.5 - 6.0 = 6.5$ م. وكل سقف عليه شكالات عند طرفيه هو (الباكيتين 1 و 3، والباكيتين 4 و 6)، والخطوط الطولية بتتدرج على محور الدرجة."}},{t:"p",text:{en:"**Struts on a stepped wall.** On the column wall the tiers are counted on the height up to the eaves — 7.75 m in the low part, 11.25 m in the high part — and the struts run continuously along the whole wall, so the high part takes the levels of the low part. The low wall gets one X from 0 to 7.75 m with its strut at 3.875 m through the crossing ($\\tan^{-1}(7.75/6) = 52.3^\\circ$); the high wall the same X and strut, then a strut at 7.75 m and one more X up to 11.25 m ($\\tan^{-1}(3.5/6) = 30.3^\\circ$). By height alone two tiers would do for 11.25 m; matching the low levels gives three, and every strut stays one continuous member.",ar:"**الأعضاء الأفقية في حائط متدرج.** على حائط الأعمدة الأدوار بتتحسب على الارتفاع لحد الـ Eaves — 7.75 م في الجزء الواطي و 11.25 م في العالي — والأعضاء الأفقية مستمرة بطول الحائط كله، فالجزء العالي بياخد مناسيب الجزء الواطي. الحائط الواطي بياخد X واحدة من 0 لـ 7.75 م وعضوها الأفقي عند 3.875 م بيعدّي من تقاطعها ($\\tan^{-1}(7.75/6) = 52.3^\\circ$)؛ والحائط العالي نفس الـ X ونفس العضو، وبعدين عضو أفقي عند 7.75 م و X كمان لحد 11.25 م ($\\tan^{-1}(3.5/6) = 30.3^\\circ$). بالارتفاع لوحده دورين كانوا يكفّوا الـ 11.25 م؛ لكن مطابقة المناسيب الواطية بتدّي تلاتة، وكل عضو أفقي بيفضل عضو واحد مستمر."}},{t:"p",text:{en:"**Two heavy trusses on one line.** Two blocks of different heights that touch along part of a long line, with no columns allowed there, need **one heavy truss per roof** on that line: the low one at the low level, the high one above it, both on **full-height cross columns** at the two ends of the shared stretch. Each needs its **own H.B2 strip, at its own level**, in its own roof. **Example:** two 20 m wide blocks (trusses 1.25 m at the columns, 1.75 m at the ridge) share 18 m (three bays of 6 m) of one line; clear heights 12.0 m and 7.0 m. Both heavy trusses: $18/(10\\sim12) = 1.50$–$1.80$ m, not less than 1.25 m → 1.50 m, in panels of 1.5 m (45°). High: lower chord at 12.0 m, top at 13.5 m, eaves 12.25 m; low: 7.0 m, 8.5 m, eaves 7.25 m. The low walls (7.25 m) take two tiers with a strut at 3.625 m; the high walls (12.25 m) three — the upper strut at the level of the low roof top, 8.5 m, where the two blocks meet, the lower one at 4.25 m (tiers 4.25 / 4.25 / 3.75 m, X at 35.3° and 32.0°).",ar:"**جمالونين تقال على خط واحد.** بلوكين بارتفاعين مختلفين بيلمسوا بعض على جزء من خط طويل، والأعمدة ممنوعة هناك، محتاجين **جمالون تقيل لكل سقف** على الخط ده: الواطي في المنسوب الواطي، والعالي فوقه، والاتنين على **أعمدة صليبة بالارتفاع كله** عند طرفين الجزء المشترك. وكل واحد محتاج **شريط H.B2 بتاعه، في منسوبه هو**، في سقفه هو. **مثال:** بلوكين عرض كل واحد 20 م (الجمالونات 1.25 م عند الأعمدة و 1.75 م عند الـ Ridge) مشتركين في 18 م (تلات باكيات كل واحدة 6 م) من خط واحد؛ والارتفاعات الصافية 12.0 م و 7.0 م. الجمالونين التقال: $18/(10\\sim12) = 1.50$–$1.80$ م، ومش أقل من 1.25 م ← 1.50 م، ببواكي 1.5 م (45°). العالي: الوتر السفلي عند 12.0 م، والعلوي عند 13.5 م، والـ Eaves عند 12.25 م؛ والواطي: 7.0 م و 8.5 م، والـ Eaves عند 7.25 م. الحوائط الواطية (7.25 م) بتاخد دورين بعضو أفقي عند 3.625 م؛ والعالية (12.25 م) تلاتة — العضو الأفقي العلوي في منسوب سطح البلوك الواطي، 8.5 م، مكان ما البلوكين بيتقابلوا، والتاني عند 4.25 م (أدوار 4.25 / 4.25 / 3.75 م، والـ X عند 35.3° و 32.0°)."}},{t:"quiz",q:{kind:"num",q:{en:"Clear height 8.0 m under a 1.60 m heavy truss; the trusses are 1.25 m deep at the columns; the column wall is braced in two tiers. The level of its strut (m)?",ar:"ارتفاع صافي 8.0 م تحت جمالون تقيل 1.60 م؛ والجمالونات عمقها 1.25 م عند الأعمدة؛ وحائط الأعمدة شكالاته على دورين. منسوب العضو الأفقي (م)؟"},answer:4.175,tol:.002,unit:"m",explain:{en:"The eaves are at $8.0 + 1.60 - 1.25 = 8.35$ m ≥ 6 m → two tiers, the strut at $8.35/2 = 4.175$ m, continuous along the wall.",ar:"الـ Eaves عند $8.0 + 1.60 - 1.25 = 8.35$ م ≥ 6 م ← دورين، والعضو الأفقي عند $8.35/2 = 4.175$ م، ومستمر بطول الحائط."}}}]},{id:"skylight",title:{en:"A raised skylight over a wide hall",ar:"شخشيخة مرفوعة فوق صالة واسعة"},blocks:[{t:"p",text:{en:"A skylight raised above the roof interrupts the main trusses under it. Along its two edges run **heavy trusses** that carry the interrupted truss ends; on them stands the **skylight truss**, lifted on short posts (about 1.6 m) so the light enters through the vertical faces. Bracing strips run behind both heavy trusses, and the skylight gets its own bracing. The main trusses of a wide hall stay N-trusses as long as their diagonals remain within 30°–60° — a flat 1:20 slope helps, and keeps an N-truss acceptable even a little beyond the usual 34 m.",ar:"الشخشيخة المرفوعة فوق السقف بتقطع الجمالونات الرئيسية اللي تحتها. وعلى حرفيها ماشيين **جمالونات تقيلة** شايلة أطراف الجمالونات المقطوعة؛ وعليهم واقف **جمالون الشخشيخة**، مرفوع على أعمدة قصيرة (حوالي 1.6 م) علشان النور يدخل من الوشوش الرأسية. وشرايح شكالات ماشية ورا الجمالونين التقال، والشخشيخة ليها شكالاتها. والجمالونات الرئيسية في الصالة الواسعة بتفضل N طول ما أقطارها بين 30° و 60° — والميل المفلطح 1:20 بيساعد، وبيخلي جمالون N مقبول حتى بعد الـ 34 م المعتادة بشوية."}},{t:"p",text:{en:"**Example — a 32 × 48 m hall** (8 bays of 6 m, clear height 7 m). The 32 m trusses: $H = 32/12 = 2.67 \\to 2.65$ m, $h = 2.65 - 16/20 = 1.85$ m, sixteen panels of 2.0 m, diagonals at 42.8° and 53.0° → an N-truss. A 12 m wide skylight over the middle band (10–22 m) along three bays: two heavy trusses at 10 m and 22 m span 18 m. $18/12 = 1.50$ m would be enough for their span, but their chords must meet the chords of the interrupted trusses: they take the main-truss depth on their line, $1.85 + 10/20 = 2.35$ m. The skylight truss spans 12 m on 1.6 m posts.",ar:"**مثال — صالة 32 × 48 م** (8 باكيات كل واحدة 6 م، وارتفاع صافي 7 م). جمالونات الـ 32 م: $H = 32/12 = 2.67 \\to 2.65$ م، و $h = 2.65 - 16/20 = 1.85$ م، وستاشر باكية كل واحدة 2.0 م، والأقطار عند 42.8° و 53.0° ← جمالون N. وشخشيخة عرضها 12 م فوق الشريط اللي في النص (10–22 م) على طول تلات باكيات: جمالونين تقال عند 10 م و 22 م بحرهم 18 م. $18/12 = 1.50$ م كانت هتكفي لبحرهم، لكن أوتارهم لازم تقابل أوتار الجمالونات المقطوعة: فبياخدوا عمق الجمالون الرئيسي على خطهم، $1.85 + 10/20 = 2.35$ م. وجمالون الشخشيخة بحره 12 م على أعمدة 1.6 م."}},{t:"p",text:{en:"**The skylight itself.** Its truss follows the main-truss rules over the skylight width: $12/(12\\sim16) = 0.75$–$1.00$ m → the 1.25 m minimum, standing on 1.6 m posts on the two heavy trusses, which rest on the full trusses at the skylight ends (these become heavy trusses too). In the 48 m hall let the skylight cover bays 4–6. It is braced in its own two end bays: X in its roof and V's on its two edge lines, in the post band and in the depth of the skylight truss alike; the main roof is braced in the same bays 4 and 6 besides its end bays 1 and 8 (gaps of 12, 6 and 6 m ✓). The ridge longitudinal line of the main trusses exists only outside the skylight — over it the skylight truss takes its place — and the H.B2 strips behind both heavy trusses run the whole length of the hall, so that they end in the braced end bays. The edge line may also be drawn as one truss over the whole hall, as deep as the trusses on that line: over the skylight it is the heavy truss, beyond it the longitudinal-bracing band of that line.",ar:"**الشخشيخة نفسها.** جمالونها بيمشي بقواعد الجمالون الرئيسي على عرض الشخشيخة: $12/(12\\sim16) = 0.75$–$1.00$ م ← الحد الأدنى 1.25 م، واقف على أعمدة 1.6 م فوق الجمالونين التقال، اللي راكبين على الجمالونين الكاملين عند طرفين الشخشيخة (ودول بيبقوا جمالونات تقيلة هما كمان). في الصالة 48 م خلّي الشخشيخة على الباكيات 4–6. شكالاتها في باكيتيها الطرفيتين: X في سقفها و V على خطين حرفيها، في شريط الأعمدة القصيرة وفي عمق جمالون الشخشيخة الاتنين؛ والسقف الرئيسي عليه شكالات في نفس الباكيتين 4 و 6 جنب باكياته الطرفية 1 و 8 (المسافات 12 و 6 و 6 م ✓). وخط الشكالات الطولية اللي عند Ridge الجمالونات الرئيسية موجود بس برّه الشخشيخة — فوقها جمالون الشخشيخة بياخد مكانه — وشرايح الـ H.B2 اللي ورا الجمالونين التقال ماشية بطول الصالة كلها، علشان تخلص في الباكيات الطرفية اللي فيها شكالات. وخط الحرف ممكن كمان يترسم جمالون واحد على طول الصالة، عمقه قد عمق الجمالونات على الخط ده: فوق الشخشيخة هو الجمالون التقيل، وبرّاها هو شريط الشكالات الطولية للخط ده."}},{t:"quiz",q:{kind:"num",q:{en:"A truss with h = 1.60 m at the columns and a 20:1 slope: its depth 8 m from the column (m)?",ar:"جمالون h = 1.60 م عند الأعمدة وميله 20:1: عمقه على بعد 8 م من العمود (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"$1.60 + 8/20 = 2.00$ m — the depth a skylight heavy truss on that line takes.",ar:"$1.60 + 8/20 = 2.00$ م — العمق اللي جمالون الشخشيخة التقيل على الخط ده بياخده."}}}]},{id:"plans",title:{en:"T, L, Π and cross-shaped plans",ar:"مساقط T و L و Π والصليب"},blocks:[{t:"p",text:{en:"Irregular plans are split into rectangles, each spanned in its own short direction; the heavy truss goes where two rectangles meet without columns. Narrow arms keep the minimum truss depth: a 12 m span gives only 12/(12–16) = 0.75–1.00 m, so it takes the 1.25 m minimum.",ar:"المساقط غير المنتظمة بتتقسم لمستطيلات، كل واحد بيتغطى في اتجاهه القصير؛ والجمالون التقيل بيتحط مكان ما مستطيلين بيتقابلوا من غير أعمدة. والدراعات الضيقة بتاخد الحد الأدنى للعمق: بحر 12 م بيدّي 12/(12–16) = 0.75–1.00 م بس، فبياخد الحد الأدنى 1.25 م."}},{t:"table",head:[{en:"Plan",ar:"المسقط"},{en:"Solution",ar:"الحل"}],rows:[[{en:"T, stem length B₁ shorter than its width L",ar:"T، طول الساق B₁ أقصر من عرضها L"},{en:"stem trusses span B₁, in line with the bar trusses: a heavy truss on the junction line (span L), carrying trusses from both sides — case 2",ar:"جمالونات الساق على B₁، على نفس خط جمالونات القضيب: جمالون تقيل على خط التقابل (بحره L)، شايل جمالونات من الناحيتين — الحالة 2"}],[{en:"T, stem width L shorter than its length B₁",ar:"T، عرض الساق L أقصر من طولها B₁"},{en:"stem trusses span L, parallel to the junction: the heavy truss carries the bar trusses and the stem purlins — case 3, avoid if you can",ar:"جمالونات الساق على L، موازية لخط التقابل: الجمالون التقيل شايل جمالونات القضيب ومدادات الساق — الحالة 3، ابعد عنها لو تقدر"}],[{en:"L (columns on the outline only)",ar:"L (أعمدة على المحيط بس)"},{en:"continuous truss lines across both arms, a heavy truss on the re-entrant line — case 2",ar:"خطوط جمالونات مستمرة على الدراعين، وجمالون تقيل على الخط الداخلي — الحالة 2"}],[{en:"Π (U)",ar:"Π (U)"},{en:"two heavy trusses on the two sides of the notch",ar:"جمالونين تقال على جنبي النقص"}],[{en:"cross or plus with two interior columns",ar:"صليب أو علامة زائد بعمودين داخليين"},{en:"heavy trusses along the lines through the interior columns, continuous over them",ar:"جمالونات تقيلة على الخطوط اللي بتعدّي على العمودين الداخليين، مستمرة فوقهم"}],[{en:"rectangle with a semicircular apse",ar:"مستطيل بآخره نص دايرة"},{en:"radial members (radial half-trusses or solid-web rafters) from the apse columns to a ring beam at the ridge of the last truss",ar:"أعضاء قطرية (أنصاص جمالونات قطرية أو Rafters بعصب مصمت) من أعمدة نص الدايرة لكمرة حلقية عند Ridge آخر جمالون"}]],caption:{en:"In case 2 keep the same spacing S₁ on both sides of the heavy truss; elsewhere the plot may use another spacing S₂.",ar:"في الحالة 2 خلّي نفس المسافة S₁ على ناحيتين الجمالون التقيل؛ وباقي الأرض ممكن تاخد مسافة تانية S₂."}},{t:"p",text:{en:"**Example — a T plot:** the bar is 20 m wide; the stem is L = 24 m wide and B₁ = 16 m long. B₁ < L, so the stem trusses span its 16 m, in line with the 20 m bar trusses, and a heavy truss of $24/12 = 2.0$ m spans the 24 m junction — ≥ 1.25 m, the depth of the bar and stem trusses where their ends sit on it ✓ (their 1.75 m and 1.65 m ridge depths do not count). Were the stem 30 m long, it would span its 24 m width parallel to the junction — case 3.",ar:"**مثال — أرض على شكل T:** القضيب عرضه 20 م؛ والساق عرضها L = 24 م وطولها B₁ = 16 م. B₁ < L، فجمالونات الساق على الـ 16 م بتاعتها، على نفس خط جمالونات القضيب 20 م، وجمالون تقيل $24/12 = 2.0$ م بيعدّي خط التقابل 24 م — ≥ 1.25 م، عمق جمالونات القضيب والساق عند ارتكاز أطرافها عليه ✓ (وعمقها عند الـ Ridge، 1.75 م و 1.65 م، مش هو اللي بيتقارن). ولو الساق طولها 30 م، كانت هتتغطى على عرضها 24 م موازية لخط التقابل — الحالة 3."}},{t:"p",text:{en:"**Bracing a T.** Let the bar of that plot be 60 m long (ten bays of 6 m, frames A–K) with the stem on its middle 24 m (frames D–H). *Stem in line (case 2):* the bar is braced at its two ends (A–B, J–K) and in the bays just outside the junction (C–D, H–I). Those are also the bays where the junction wall gets its X: the heavy truss takes the place of the wall between them, and these X's receive its H.B2, which runs along the heavy truss on the bar side (D–H). The stem is braced in its two end bays (D–E, G–H), and its far wall gets X in the same bays; every gap stays ≤ 24 m ✓. In the section through the junction the heavy truss is cut — a small section with both lower chords inclined down to it. *Stem parallel to the junction (case 3):* the stem bay directly behind the heavy truss is X-braced over the whole stem width; it closes the stem roof at that end **and** is the H.B2 of the heavy truss, so the bar needs no strip there. The far end bay of the stem is braced too, the stem side walls get X in the same two bays, and in the sections through the bar the stem's longitudinal bands appear behind the heavy truss, with their V's in the braced bays.",ar:"**شكالات الـ T.** خلّي القضيب في الأرض دي طوله 60 م (عشر باكيات كل واحدة 6 م، والإطارات من A لـ K) والساق على الـ 24 م اللي في نصه (الإطارات من D لـ H). *الساق على نفس الخط (الحالة 2):* القضيب عليه شكالات عند طرفيه (A–B و J–K) وفي الباكيات اللي برّه خط التقابل على طول (C–D و H–I). ودي نفسها الباكيات اللي حائط التقابل بياخد فيها X: الجمالون التقيل واخد مكان الحائط بينهم، والـ X دي هي اللي بتستلم الـ H.B2 بتاعه، اللي ماشي بطول الجمالون التقيل من ناحية القضيب (D–H). والساق عليها شكالات في باكيتيها الطرفيتين (D–E و G–H)، وحائطها البعيد بياخد X في نفس الباكيتين؛ وكل المسافات ≤ 24 م ✓. وفي القطاع اللي بيعدّي على خط التقابل الجمالون التقيل بيظهر مقطوع — قطاع صغير والأوتار السفلية نازلة له مايلة من الناحيتين. *الساق موازية لخط التقابل (الحالة 3):* باكية الساق اللي ورا الجمالون التقيل على طول بتاخد X على عرض الساق كله؛ بتقفل سقف الساق من الناحية دي **وهي كمان** الـ H.B2 بتاع الجمالون التقيل، فالقضيب مش محتاج شريط هناك. والباكية الطرفية البعيدة للساق عليها شكالات كمان، وحوائط الساق الجانبية بتاخد X في نفس الباكيتين، وفي القطاعات اللي بتعدّي على القضيب بتظهر شرايح الشكالات الطولية بتاعة الساق ورا الجمالون التقيل، والـ V بتاعتها في باكيات الشكالات."}},{t:"p",text:{en:"**The apse.** Each radial member may be a radial half-truss (its upper chord rising to the ring) or a solid-web rafter; both end on the ring beam, which hangs on the ridge longitudinal band of the last truss of the rectangle. Ring purlins run between the radial members. The apse is braced in one of its bays like an end bay, and its curved wall is drawn as a developed elevation that continues the side walls, with the X's (and the V's in the truss band) in the same bays as the roof bracing.",ar:"**نص الدايرة.** كل عضو قطري ممكن يبقى نص جمالون قطري (وتره العلوي طالع لحد الحلقة) أو Rafter بعصب مصمت (Solid-web)؛ والاتنين بيخلصوا على الكمرة الحلقية، اللي متعلقة على شريط الشكالات الطولية اللي عند Ridge آخر جمالون في المستطيل. والمدادات الدائرية ماشية بين الأعضاء القطرية. ونص الدايرة بياخد شكالات في باكية من باكياته زي الباكية الطرفية، وحائطه المقوّس بيترسم على واجهة مفرودة مكمّلة للحوائط الجانبية، والـ X (والـ V في شريط الجمالون) في نفس باكيات شكالات السقف."}},{t:"quiz",q:{kind:"mcq",q:{en:"A T plot: stem 18 m wide and 30 m long. The heavy truss on the junction is…",ar:"أرض T: الساق عرضها 18 م وطولها 30 م. الجمالون التقيل على خط التقابل…"},options:[{en:"case 3 (the stem trusses run parallel to it)",ar:"الحالة 3 (جمالونات الساق موازية ليه)"},{en:"case 2",ar:"الحالة 2"},{en:"not needed",ar:"مش محتاجينه"}],answer:0,explain:{en:"Its short side is its 18 m width: the stem trusses span it, parallel to the junction; the heavy truss must also carry their purlins.",ar:"ضلعها القصير هو عرضها 18 م: جمالونات الساق عليه، موازية لخط التقابل؛ والجمالون التقيل لازم يشيل مداداتها كمان."}}}]},{id:"cross",title:{en:"Cross and plus plans on two interior columns",ar:"مساقط الصليب وعلامة الزائد على عمودين داخليين"},blocks:[{t:"p",text:{en:"**A cross** — a long body with a short wing at each end — with two interior columns allowed on the middle frame of the body. The two lines that bound the wings run through those columns, and on each of them stands a **heavy truss continuous over its interior column**, carried at its ends by the columns of the body's end walls. The trusses of the body run across in three pieces — wall to heavy truss, heavy truss to heavy truss, heavy truss to wall — and the wings are covered by ordinary trusses on columns along the same two lines, which become the wings' side walls, braced with X.",ar:"**الصليب** — جسم طويل وجناح قصير عند كل طرف — والمسموح عمودين داخليين على الإطار اللي في نص الجسم. الخطين اللي بيحدّدوا الجناحين بيعدّوا على العمودين دول، وعلى كل واحد منهم **جمالون تقيل مستمر فوق عموده الداخلي**، وطرفيه راكبين على أعمدة الحوائط الطرفية للجسم. وجمالونات الجسم ماشية بالعرض على تلات حتت — من الحائط للجمالون التقيل، ومن جمالون تقيل للتاني، ومن الجمالون التقيل للحائط — والجناحين بيتغطوا بجمالونات عادية على أعمدة على نفس الخطين، اللي بيبقوا الحوائط الجانبية للجناحين وعليهم X."}},{t:"p",text:{en:"**Example — a body of 40 × 36 m** (eight bays of 5 m; across 10 | 16 | 10 m) **with wings 5 m long and 16 m wide**: frames A–K every 5 m (wings A–B and J–K, body B–J), interior columns on frame F at 10 and 26 m. Heavy trusses: 2 × 20 m, $20/(10\\sim12) = 1.67$–$2.00$ m → **1.70 m** (≥ the 1.25 m ends they carry ✓), three panels of 1.667 m per bay (45.6°). The 10 m outer trusses take the 1.25 m minimum ($10/(12\\sim16) = 0.63$–$0.83$ m), with parallel chords; the 16 m middle and wing trusses are 1.25 m at their ends and $1.25 + 8/20 = 1.65$ m at the ridge; on frame F the middle truss sits directly on the two interior columns. Levels: 6.0 m clear under the heavy trusses, their top and every upper chord at 7.70 m, the eaves at $7.70 - 1.25 = 6.45$ m, the middle ridge at $7.70 + 0.40 = 8.10$ m; girts over a 3.0 m dado at 4.725 and 6.45 m (two spaces of 1.725 m), and a wall strut at 3.225 m (6.45 m ≥ 6 m). The end walls of the body have columns at 0, 10, 26 and 36 m and are clad only on their 10 m parts — the middle 16 m opens into the wing. Roof bracing by zones: the outer zones in bays B–C, F–G and I–J; the middle zone in the wing end bays A–B and J–K and in F–G; and an H.B2 strip along each heavy truss, on the middle side, over the whole body.",ar:"**مثال — جسم 40 × 36 م** (تمن باكيات كل واحدة 5 م؛ وبالعرض 10 | 16 | 10 م) **وجناحين طول كل واحد 5 م وعرضه 16 م**: الإطارات من A لـ K كل 5 م (الجناحين A–B و J–K، والجسم B–J)، والعمودين الداخليين على الإطار F عند 10 و 26 م. الجمالونات التقيلة: 2 × 20 م، $20/(10\\sim12) = 1.67$–$2.00$ م ← **1.70 م** (≥ الأطراف 1.25 م اللي شايلها ✓)، تلات بواكي كل واحدة 1.667 م في الباكية (45.6°). الجمالونات البرانية 10 م بتاخد الحد الأدنى 1.25 م ($10/(12\\sim16) = 0.63$–$0.83$ م)، بأوتار متوازية؛ وجمالونات النص والجناحين 16 م: 1.25 م عند أطرافها و $1.25 + 8/20 = 1.65$ م عند الـ Ridge؛ وعلى الإطار F جمالون النص راكب على العمودين الداخليين على طول. المناسيب: 6.0 م صافي تحت الجمالونات التقيلة، ووترها العلوي وكل الأوتار العلوية عند 7.70 م، والـ Eaves عند $7.70 - 1.25 = 6.45$ م، والـ Ridge بتاع النص عند $7.70 + 0.40 = 8.10$ م؛ والـ Girts فوق حائط طوب 3.0 م عند 4.725 و 6.45 م (مسافتين كل واحدة 1.725 م)، وعضو أفقي في الحوائط عند 3.225 م (6.45 م ≥ 6 م). والحوائط الطرفية للجسم أعمدتها عند 0 و 10 و 26 و 36 م ومتكسية على أجزائها الـ 10 م بس — والـ 16 م اللي في النص مفتوحة على الجناح. وشكالات السقف بالمناطق: المناطق البرانية في الباكيات B–C و F–G و I–J؛ ومنطقة النص في باكيتين الجناحين الطرفيتين A–B و J–K وفي F–G؛ وشريط H.B2 بطول كل جمالون تقيل، من ناحية النص، على الجسم كله."}},{t:"p",text:{en:"**A plus** — a central band across the whole width and a narrower arm at each end — puts both interior columns on the centre line. There **one heavy truss** runs the whole length, continuous over **four supports**: the two arm-end walls and the two interior columns. Every truss rests on it from both sides (case 2): long ones in the central band, short ones in the arms. On each junction line, where an arm meets the band, **one continuous truss** runs across the whole width on **five columns** — the two outer walls, the two re-entrant corners and the interior column. **Example:** a band 36 m wide and 20 m long with arms 20 m wide and 10 m long (across 8 | 20 | 8 m, along 10 | 20 | 10 m). The heavy truss spans 10 | 20 | 10 m and takes its depth from the 20 m span, $20/(10\\sim12)$ → 1.70 m; the band trusses span 18 + 18 m, the arm trusses 10 + 10 m, and the junction trusses 8 | 10 | 10 | 8 m. Roof bracing: across each arm in its end bay, across the whole 36 m in the two end bays of the band, and a strip on one side of the heavy truss in all the other bays.",ar:"**علامة الزائد** — شريط في النص على العرض كله ودراع أضيق عند كل طرف — العمودين الداخليين فيها على خط النص. وهناك **جمالون تقيل واحد** ماشي على الطول كله، مستمر فوق **أربع ركائز**: حائطين طرفين الدراعين والعمودين الداخليين. وكل الجمالونات راكبة عليه من الناحيتين (الحالة 2): الطويلة في الشريط اللي في النص، والقصيرة في الدراعين. وعلى كل خط تقابل، مكان ما دراع بيقابل الشريط، **جمالون واحد مستمر** على العرض كله على **خمس أعمدة** — الحائطين الخارجيين، والركنين الداخليين، والعمود الداخلي. **مثال:** شريط عرضه 36 م وطوله 20 م ودراعين عرض كل واحد 20 م وطوله 10 م (بالعرض 8 | 20 | 8 م، وبالطول 10 | 20 | 10 م). الجمالون التقيل بحوره 10 | 20 | 10 م وعمقه من بحره الـ 20 م، $20/(10\\sim12)$ ← 1.70 م؛ وجمالونات الشريط بحورها 18 + 18 م، وجمالونات الدراعين 10 + 10 م، وجمالونات خطوط التقابل 8 | 10 | 10 | 8 م. وشكالات السقف: بعرض كل دراع في باكيته الطرفية، وبعرض الـ 36 م كلها في باكيتين الشريط الطرفيتين، وشريط على ناحية واحدة من الجمالون التقيل في باقي الباكيات."}},{t:"quiz",q:{kind:"num",q:{en:"A cross plan: heavy trusses over 24 m spans taken at span/12, 6.0 m clear under them, the trusses 1.25 m deep where they sit. The eaves (m)?",ar:"مسقط صليب: جمالونات تقيلة على بحور 24 م متاخدة بالبحر/12، و 6.0 م صافي تحتها، والجمالونات عمقها 1.25 م عند ارتكازها. الـ Eaves (م)؟"},answer:6.75,tol:.002,unit:"m",explain:{en:"$H_{heavy} = 24/12 = 2.0$ m; eaves $= 6.0 + 2.0 - 1.25 = 6.75$ m.",ar:"$H_{heavy} = 24/12 = 2.0$ م؛ والـ Eaves $= 6.0 + 2.0 - 1.25 = 6.75$ م."}}}]},{id:"hinged",title:{en:"A car shed on hinged bases",ar:"مظلة عربيات على قواعد مفصلية"},blocks:[{t:"p",text:{en:"On weak soil the bases are hinged. A cantilever truss on a hinged column is a **mechanism**: nothing resists the moment of the cantilever. The cure is a second, **horizontal** support for every cantilever: a **horizontal truss along the tips** (it gives each cantilever a reaction X₂) whose own reactions X₃ are carried by **braced towers** in the two end walls — two columns near the tip on each end wall, X-braced between them in tiers.",ar:"على تربة ضعيفة القواعد بتبقى مفصلية. والجمالون الكابولي على عمود مفصلي = **ميكانيزم**: مفيش حاجة بتقاوم عزم الكابولي. والعلاج ركيزة تانية **أفقية** لكل كابولي: **جمالون أفقي بطول الأطراف** (بيدّي كل كابولي رد فعل X₂) وردود أفعاله X₃ بتشيلها **أبراج مربوطة** في الحائطين الطرفيين — عمودين جنب الطرف في كل حائط طرفي، وبينهم X على أدوار."}},{t:"p",text:{en:"**Example — a 7 m car shed 28 m long** (4 bays of 7 m, clear 5 m, hinged bases): $H = 7/5 = 1.40$ m at the column, 0.70 m at the tip, four panels of 1.75 m. The tip truss runs in the strip between 5.25 m and the tip; the end towers stand on the same two lines.",ar:"**مثال — مظلة عربيات 7 م طولها 28 م** (4 باكيات كل واحدة 7 م، وصافي 5 م، وقواعد مفصلية): $H = 7/5 = 1.40$ م عند العمود، و 0.70 م عند الطرف، وأربع بواكي كل واحدة 1.75 م. جمالون الطرف ماشي في الشريط بين 5.25 م والطرف؛ والأبراج الطرفية واقفة على نفس الخطين."}},{t:"p",text:{en:"**Following the forces.** Each frame — a hinged column with its cantilever truss — gets a vertical Y₁ and a horizontal X₁ at its hinge, and a horizontal X₂ from the tip truss at its tip. Under gravity alone nothing else pushes sideways, so $X_1 = X_2$, and moments about the hinge give them: $X_2 = P\\,(c/2)/y$, with P the roof load of the frame and y the height of the tip truss above the hinge. The tip truss is a horizontal truss loaded by X₂ at every frame; its end reactions X₃ go to the braced towers, which take them down to the ground. **In the 7 m shed** (1.2 kN/m²): $P = 1.2\\times7\\times7 = 58.8$ kN acting 3.5 m from the column and the tip truss at $y = 5.0 + 0.70 = 5.70$ m, so $X_1 = X_2 = 58.8\\times3.5/5.70 = 36.1$ kN at every inner frame (half at the two end frames), and $X_3 = (3\\times36.1 + 2\\times18.05)/2 = 72.2$ kN at each tower.",ar:"**تابع القوى.** كل إطار — عمود مفصلي بجمالونه الكابولي — بياخد عند مفصلته رد فعل رأسي Y₁ وأفقي X₁، وعند طرفه رد فعل أفقي X₂ من جمالون الطرف. وتحت الأحمال الرأسية بس مفيش حاجة تانية بتزق من الجنب، فـ $X_1 = X_2$، والعزوم حوالين المفصلة بتحددهم: $X_2 = P\\,(c/2)/y$، و P حمل السقف على الإطار و y ارتفاع جمالون الطرف فوق المفصلة. وجمالون الطرف جمالون أفقي متحمّل بـ X₂ عند كل إطار؛ وردود أفعاله عند طرفيه X₃ بتروح للأبراج المربوطة، والأبراج بتنزّلها للأرض. **في المظلة 7 م** (1.2 kN/m²): $P = 1.2\\times7\\times7 = 58.8$ kN على بعد 3.5 م من العمود، وجمالون الطرف عند $y = 5.0 + 0.70 = 5.70$ م، يبقى $X_1 = X_2 = 58.8\\times3.5/5.70 = 36.1$ kN عند كل إطار داخلي (والنص عند الإطارين الطرفيين)، و $X_3 = (3\\times36.1 + 2\\times18.05)/2 = 72.2$ kN عند كل برج."}},{t:"p",text:{en:"**Its parts.** The tip truss is a W in the strip between the last two panel points, through the middle bays; in the two end bays the roof X cover the whole cantilever, and their outer panels complete the tip truss. Each tower is the pair of end-wall columns nearest the tip, X-braced in tiers — here 1.75 m apart and 5.0 m high, so one X would stand at $\\tan^{-1}(5.0/1.75) = 70.7^\\circ$ and two tiers of 2.5 m at 55.0° ✓ — and its top tier is the last panel of the end cantilever truss, crossed as well. The column line is braced in its end bays like any wall. The taper is a choice: the tip may keep half the column depth, as here, or about three quarters of it ($0.75\\times1.40 = 1.05$ m), and the chords may also rise towards the tip so that the roof drains back towards the column line.",ar:"**أجزاؤها.** جمالون الطرف W في الشريط اللي بين آخر عقدتين، على طول الباكيات اللي في النص؛ وفي الباكيتين الطرفيتين الـ X بتاعة السقف مغطية الكابولي كله، وبواكيها البرانية بتكمّل جمالون الطرف. وكل برج هو العمودين اللي في الحائط الطرفي الأقرب للطرف، وبينهم X على أدوار — هنا بينهم 1.75 م وارتفاعهم 5.0 م، فـ X واحدة كانت هتبقى بزاوية $\\tan^{-1}(5.0/1.75) = 70.7^\\circ$ ودورين كل واحد 2.5 م بـ 55.0° ✓ — ودوره الأخير فوق هو آخر باكية في الجمالون الكابولي الطرفي، وعليها X هي كمان. وخط الأعمدة عليه شكالات في باكياته الطرفية زي أي حائط. وقلة العمق ناحية الطرف اختيار: الطرف ممكن يفضل بنص عمق العمود، زي هنا، أو حوالي تلات أرباعه ($0.75\\times1.40 = 1.05$ م)، والأوتار ممكن كمان تطلع ناحية الطرف علشان مية السقف ترجع ناحية خط الأعمدة."}},{t:"lab",lab:"shed",height:500,props:{preset:"hinged",missions:r,defaultTab:"steps"},caption:{en:"The hinged car shed tips over — add the tip truss.",ar:"مظلة العربيات المفصلية بتقع — زوّد جمالون الطرف."}},{t:"quiz",q:{kind:"tf",q:{en:"A cantilever truss standing on one hinged column is stable.",ar:"الجمالون الكابولي الواقف على عمود مفصلي واحد مستقر."},answer:!1,explain:{en:"One hinge cannot take the cantilever moment: a horizontal support at the tip (X₂) is needed.",ar:"مفصلة واحدة متقدرش تشيل عزم الكابولي: محتاج ركيزة أفقية عند الطرف (X₂)."}}}]},{id:"apply",title:{en:"Your workshop in the studio: a car-shed canopy",ar:"ورشتك في الاستوديو: مظلة عربيات"},blocks:[{t:"p",text:{en:"The owner wants cars parked under a **5 m canopy along the left wall** of the workshop. Cantilever trusses fixed to the left columns do it (5 m ≤ 12 m): $H = 5/5 = 1.00$ m at the column with the upper chord at the eaves (6.0 m), 0.50 m at the tip (1:10), three panels of 1.667 m, a longitudinal line at the tip (3a) and the diagonals running down towards the tip, in tension. **Loads by ECP 201** (single-skin sheets 6 kg/m², steel 20 kg/m², inaccessible roof at 1:10, 53.3 kg/m²): per joint $P_{DL} = 260.3$ kg and $P_{LL} = 533.3$ kg, factored $P_u = (1.2\\times260.3 + 1.6\\times533.3)/100 = 11.66$ kN (half at the tip). At the column: $M = 11.66\\times(1.667 + 3.333) + 5.83\\times5.0 = 87.4$ kN·m, and the upper chord pulls with $T = 87.4/1.00 = 87.4$ kN. That moment enters the HEB 300 columns — their fixed bases can take it, but the columns must now be checked for it (the beam-column episodes).",ar:"المالك عايز العربيات تركن تحت **مظلة 5 م بطول الحائط الشمال** للورشة. جمالونات كابولي متثبتة في الأعمدة الشمال بتعملها (5 م ≤ 12 م): $H = 5/5 = 1.00$ م عند العمود والوتر العلوي عند الـ Eaves (6.0 م)، و 0.50 م عند الطرف (1:10)، وتلات بواكي كل واحدة 1.667 م، وخط شكالات طولية عند الطرف (3a)، والأقطار نازلة ناحية الطرف، شد. **الأحمال بالكود ECP 201** (صاج طبقة واحدة 6 كجم/م²، وحديد 20 كجم/م²، وسقف مش بيتمشي عليه بميل 1:10، يعني 53.3 كجم/م²): لكل عقدة $P_{DL} = 260.3$ كجم و $P_{LL} = 533.3$ كجم، والمضروب $P_u = (1.2\\times260.3 + 1.6\\times533.3)/100 = 11.66$ kN (والنص عند الطرف). عند العمود: $M = 11.66\\times(1.667 + 3.333) + 5.83\\times5.0 = 87.4$ kN·m، والوتر العلوي بيشد بـ $T = 87.4/1.00 = 87.4$ kN. والعزم ده بيدخل أعمدة الـ HEB 300 — قواعدها الثابتة تقدر تشيله، بس الأعمدة لازم تتراجع عليه دلوقتي (حلقات الأعمدة تحت حمل وعزم)."}},{t:"p",text:{en:"Two more studio answers for the workshop: a **2 m canopy over the far gable** is just the purlins continuing past the last truss — the last purlin becomes a 6 m beam with a 2 m cantilever, whose support moment is 0.44 of an ordinary span moment. And the **level solver** of the heavy-truss what-if of the previous episode: $6.0 + 1.8 - 0 = 7.8$ m for the new eaves (a triangular truss has h = 0).",ar:"وإجابتين كمان من الاستوديو للورشة: **مظلة 2 م فوق الواجهة البعيدة** مجرد المدادات مكمّلة بعد آخر جمالون — آخر مداد بيبقى كمرة 6 م بكابولي 2 م، وعزم ركيزته 0.44 من عزم بحر مداد عادي. و**حاسبة المناسيب** لسيناريو الجمالون التقيل في الحلقة اللي فاتت: $6.0 + 1.8 - 0 = 7.8$ م للـ Eaves الجديدة (الجمالون المثلث h = 0)."}},{t:"lab",lab:"shed",height:500,props:{preset:"wsCanopy",missions:o,defaultTab:"steps"},caption:{en:"The 5 m canopy along the workshop wall (columns at 6 m, the canopy trusses cantilevering from them).",ar:"المظلة 5 م بطول حائط الورشة (أعمدة كل 6 م، وجمالونات المظلة كابولي منها)."}},{t:"widget",w:"building",props:{focus:"WB-1",tags:["ws-columns","ws-trusses","ws-purlins","ws-bracing","ws-studio"]}},{t:"quiz",q:{kind:"num",q:{en:"Your canopy: the moment at the column (kN·m)?",ar:"مظلتك: العزم عند العمود (kN·m)؟"},answer:87.4,tol:.003,unit:"kN·m",explain:{en:"$M = 7.5\\,P_u = 7.5\\times11.66 = 87.4$ kN·m (joints at 1.667 and 3.333 m, half a joint load at 5 m).",ar:"$M = 7.5\\,P_u = 7.5\\times11.66 = 87.4$ kN·m (عقد عند 1.667 و 3.333 م، ونص حمل عقدة عند 5 م)."}}}]}],quiz:[{kind:"num",q:{en:"Clear height 6.5 m under a 3.35 m heavy truss, main trusses 1.25 m at the columns: the eaves (m)?",ar:"ارتفاع صافي 6.5 م تحت جمالون تقيل 3.35 م، والجمالونات الرئيسية 1.25 م عند الأعمدة: الـ Eaves (م)؟"},answer:8.6,tol:.002,unit:"m",explain:{en:"$6.5 + 3.35 - 1.25 = 8.60$ m.",ar:"$6.5 + 3.35 - 1.25 = 8.60$ م."}},{kind:"mcq",q:{en:"Columns are allowed at the four corners of a 20 × 36 m plot only. The system is…",ar:"الأعمدة مسموحة في الأركان الأربعة بس لأرض 20 × 36 م. النظام…"},options:[{en:"two heavy trusses along the 36 m sides, trusses spanning 20 m between them",ar:"جمالونين تقال على الأضلاع 36 م، والجمالونات على الـ 20 م بينهم"},{en:"trusses spanning 36 m",ar:"جمالونات بحرها 36 م"},{en:"cantilever trusses from the corners",ar:"جمالونات كابولي من الأركان"}],answer:0,explain:{en:"The trusses keep the short span; the two heavy trusses (36/(10–12) deep) carry them on cross columns.",ar:"الجمالونات بتفضل على البحر القصير؛ والجمالونين التقال (عمقهم 36/(10–12)) شايلينها على أعمدة صليبة."}},{kind:"num",q:{en:"Regular trusses 1.6 m deep and 9 m cantilevers at c/5 under one roof: the depth for all (m)?",ar:"جمالونات عادية عمقها 1.6 م وكوابيل 9 م على c/5 تحت سقف واحد: العمق للكل (م)؟"},answer:1.8,tol:.003,unit:"m",explain:{en:"The larger of 1.6 m and $9/5 = 1.8$ m.",ar:"الأكبر بين 1.6 م و $9/5 = 1.8$ م."}},{kind:"tf",q:{en:"A side void that leaves a 14 m overhang can be covered by cantilever trusses.",ar:"فتحة جانبية بتسيب كابولي 14 م ممكن تتغطى بجمالونات كابولي."},answer:!1,explain:{en:"Beyond 12 m: a heavy truss along the void edge, on the full trusses at its ends.",ar:"بعد 12 م: جمالون تقيل على حرف الفتحة، راكب على الجمالونات الكاملة عند طرفيها."}},{kind:"num",q:{en:"A longitudinal-bracing line 6 m from the column of a truss with h = 1.25 m at 20:1: its depth (m)?",ar:"خط شكالات طولية على بعد 6 م من عمود جمالون h = 1.25 م بميل 20:1: عمقه (م)؟"},answer:1.55,tol:.003,unit:"m",explain:{en:"$1.25 + 6/20 = 1.55$ m.",ar:"$1.25 + 6/20 = 1.55$ م."}},{kind:"num",q:{en:"Walls 13.35 m high: tiers of vertical bracing?",ar:"حوائط ارتفاعها 13.35 م: أدوار الشكالات الرأسية؟"},answer:3,tol:.001,explain:{en:"$\\lceil 13.35/6 \\rceil = 3$.",ar:"$\\lceil 13.35/6 \\rceil = 3$."}},{kind:"mcq",q:{en:"A T plot whose stem is shorter than it is wide (B₁ < L) needs a heavy truss of…",ar:"أرض T ساقها أقصر من عرضها (B₁ < L) محتاجة جمالون تقيل من…"},options:[{en:"case 2 (trusses from both sides)",ar:"الحالة 2 (جمالونات من الناحيتين)"},{en:"case 3",ar:"الحالة 3"},{en:"case 1",ar:"الحالة 1"}],answer:0,explain:{en:"The stem trusses continue the bar trusses across the junction: both sides rest on it.",ar:"جمالونات الساق مكمّلة جمالونات القضيب عبر خط التقابل: الناحيتين راكبين عليه."}},{kind:"num",q:{en:"A skylight heavy truss 8 m from the columns of trusses with h = 1.6 m at 20:1: its depth (m)?",ar:"جمالون شخشيخة تقيل على بعد 8 م من أعمدة جمالونات h = 1.6 م بميل 20:1: عمقه (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"The main-truss depth on its line: $1.6 + 8/20 = 2.0$ m.",ar:"عمق الجمالون الرئيسي على خطه: $1.6 + 8/20 = 2.0$ م."}}]};export{i as default};
